func TestCounterConcurrentInc(t *testing.T) {
	var c Counter
	const goroutines, perG = 500, 100
	var wg sync.WaitGroup
	for i := 0; i < goroutines; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for j := 0; j < perG; j++ {
				c.Inc()
			}
		}()
	}
	wg.Wait()
	if want := goroutines * perG; c.Value() != want {
		t.Errorf("Value() = %d, want %d", c.Value(), want)
	}
}

