import "testing"

func TestMerge(t *testing.T) {
	a := make(chan int)
	b := make(chan int)
	out := Merge(a, b)

	// Close inputs so the fan-in can drain.
	close(a)
	close(b)

	// Collect results.
	got := []int{}
	for v := range out {
		got = append(got, v)
	}

	want := []int{1, 2, 3, 4, 5}
	if !equalInts(got, want) {
		t.Errorf("got %v, want %v", got, want)
	}
}

// equalInts reports whether two []int are equal (order-independent).
func equalInts(a, b []int) bool {
	if len(a) != len(b) {
		return false
	}
	seen := map[int]bool{}
	for _, v := range a {
		if seen[v] {
			continue
		}
		seen[v] = true
	}
	for _, v := range b {
		if !seen[v] {
			return false
		}
	}
	return true
}

