func TestRenderUser(t *testing.T) {
	tests := []struct {
		name    string
		user    User
		want    string
		wantErr bool
	}{
		{
			name: "both fields present",
			user: User{Name: "Alice", Email: "alice@example.com"},
			want: `{"name":"Alice","email":"alice@example.com"}`,
		},
		{
			name: "email omitted",
			user: User{Name: "Bob"},
			want: `{"name":"Bob"}`,
		},
