			got, err := RenderUser(tt.user)
			if tt.wantErr {
				if err == nil {
					t.Fatalf("RenderUser(%v) = %s, want error", tt.user, got)
				}
				return
			}
			if err != nil {
				t.Fatalf("RenderUser(%v) returned unexpected error: %v", tt.user, err)
			}
			if got != tt.want {
				t.Errorf("RenderUser(%v) = %s, want %s", tt.user, got, tt.want)
			}
		})
	}
}

func TestRenderUserJSONRoundTrip(t *testing.T) {
	in := User{Name: "Cindy", Email: "cindy@example.com"}
	got, err := RenderUser(in)
	if err != nil || got == "" {
		t.Fatalf("RenderUser(%v) = %s,%v", in, got, err)
	}
	var back User
	if err := json.Unmarshal([]byte(got), &back); err != nil {
		t.Fatalf("json.Unmarshal(%s) = %v", got, err)
	}
	if !userEqual(in, back) {
		t.Errorf("round trip = %v, want %v", back, in)
	}
}

func userEqual(a, b User) bool {
	return a.Name == b.Name && a.Email == b.Email
}

